<?php session_start(); require 'config/database.php'; require 'lib_security.php'; if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: login.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['delete'])){verifyCsrf();$pdo->prepare('DELETE FROM users WHERE id=(SELECT user_id FROM teachers WHERE id=?)')->execute([(int)$_POST['delete']]);header('Location: teachers.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();$name=trim($_POST['name']);$email=trim($_POST['email']);$dept=trim($_POST['department']);$pass=$_POST['password']?:'Teacher@123';try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,"teacher")');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$pdo->prepare('INSERT INTO teachers(user_id,department) VALUES(?,?)')->execute([$pdo->lastInsertId(),$dept]);$pdo->commit();header('Location: teachers.php');exit;}catch(Throwable $e){$pdo->rollBack();$error='Email may already exist.';}}
$rows=$pdo->query('SELECT t.id,u.name,u.email,t.department FROM teachers t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC')->fetchAll();$pageTitle='Teachers';require'includes/header.php';?>
<div class="container py-4"><div class="d-flex justify-content-between"><h2>Teachers</h2><a href="admin.php" class="btn btn-outline-secondary">Dashboard</a></div><?php if(isset($error)):?><div class="alert alert-danger mt-3"><?=$error?></div><?php endif;?><div class="card shadow-sm my-3"><div class="card-body"><form method="post" class="row g-2"><?php echo csrfField(); ?><div class="col-md-3"><input name="name" class="form-control" placeholder="Full name" required></div><div class="col-md-3"><input name="email" type="email" class="form-control" placeholder="Email" required></div><div class="col-md-3"><input name="department" class="form-control" placeholder="Department"></div><div class="col-md-2"><input name="password" class="form-control" placeholder="Password"></div><div class="col-md-1"><button class="btn btn-primary">Add</button></div></form></div></div><div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Email</th><th>Department</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['email'])?></td><td><?=htmlspecialchars($r['department']??'')?></td><td><form method="post" class="d-inline" onsubmit="return confirm('Delete teacher?')"><?php echo csrfField(); ?><button name="delete" value="<?=$r['id']?>" class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require'includes/footer.php';?>
